pragma solidity >=0.8.0;
contract GasProbe {
    uint256 public entryGas;
    uint256 public exitGas;
    uint256 public midGas;
    event GasRecorded(uint256 entryG, uint256 midG, uint256 exitG);
    function getGas() public view returns (uint256) {
        return gasleft();
    }
    function recordEntry() public {
        entryGas = gasleft();
        uint256 s = 0;
        unchecked {
            for (uint256 i = 0; i < 16; i++) {
                s += i << 2;
            }
        }
        midGas = gasleft();
        exitGas = gasleft();
        emit GasRecorded(entryGas, midGas, exitGas);
    }
}
